const pptxgen = require("/usr/local/lib/node_modules/pptxgenjs");
const fs = require("fs");
const path = require("path");

// ── Palette: Ocean/Dark theme ─────────────────────────────────
const C = {
  dark:    "0A1628",  // near-black navy — title/bg
  navy:    "0D2B55",  // slide content bg
  teal:    "0891B2",  // accent
  tealLt:  "22D3EE",  // highlight
  white:   "FFFFFF",
  offWht:  "E0EAF4",
  muted:   "7CA3C8",
  card:    "112240",  // card bg on dark slide
  green:   "10B981",
  amber:   "F59E0B",
  slate:   "CBD5E1",
};

const FONT_TITLE = "Calibri";
const FONT_BODY  = "Calibri";

// ── Helpers ───────────────────────────────────────────────────
function headerBar(slide, title, { light = false } = {}) {
  // top accent line
  slide.addShape("rect", {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  // title text
  slide.addText(title, {
    x: 0.45, y: 0.14, w: 9.1, h: 0.55,
    fontFace: FONT_TITLE, fontSize: 22, bold: true,
    color: light ? C.dark : C.white,
    margin: 0
  });
  // subtle divider
  slide.addShape("rect", {
    x: 0.45, y: 0.72, w: 9.1, h: 0.02,
    fill: { color: light ? "CBD5E1" : "1E3A5F" }, line: { color: light ? "CBD5E1" : "1E3A5F" }
  });
}

function sourceLabel(slide, { light = false } = {}) {
  slide.addText("Source: HTTP Archive — State of the Web Report  |  Jan 2020 – Mar 2026", {
    x: 0.45, y: 5.4, w: 9.1, h: 0.2,
    fontFace: FONT_BODY, fontSize: 8, color: light ? "94A3B8" : "4A6A8A",
    margin: 0
  });
}

function statCard(slide, x, y, w, h, bigNum, label, sub, accent) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: C.card },
    line: { color: C.teal, width: 1 },
    shadow: { type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.25 }
  });
  // left accent bar
  slide.addShape("rect", {
    x, y, w: 0.06, h,
    fill: { color: accent || C.teal }, line: { color: accent || C.teal }
  });
  slide.addText(bigNum, {
    x: x + 0.15, y: y + 0.12, w: w - 0.2, h: h * 0.55,
    fontFace: FONT_TITLE, fontSize: 36, bold: true, color: C.tealLt,
    margin: 0, valign: "middle"
  });
  slide.addText(label, {
    x: x + 0.15, y: y + h * 0.6, w: w - 0.2, h: h * 0.22,
    fontFace: FONT_BODY, fontSize: 11, bold: true, color: C.white,
    margin: 0
  });
  if (sub) {
    slide.addText(sub, {
      x: x + 0.15, y: y + h * 0.82, w: w - 0.2, h: h * 0.18,
      fontFace: FONT_BODY, fontSize: 9, color: C.muted,
      margin: 0
    });
  }
}

// ─────────────────────────────────────────────────────────────
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title  = "State of the Web 2020–2025";
pres.author = "HTTP Archive";

// ── SLIDE 1: Title ────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.dark };

  // full-bleed geometric accent — top left block
  sl.addShape("rect", { x: 0, y: 0, w: 3.2, h: 5.625, fill: { color: "061220" }, line: { color: "061220" } });
  sl.addShape("rect", { x: 0, y: 0, w: 0.18, h: 5.625, fill: { color: C.teal }, line: { color: C.teal } });

  // teal accent bar — right side bottom
  sl.addShape("rect", { x: 3.2, y: 5.1, w: 6.8, h: 0.06, fill: { color: C.teal }, line: { color: C.teal } });

  // Decorative horizontal lines in left panel
  for (let i = 0; i < 8; i++) {
    sl.addShape("rect", {
      x: 0.35, y: 0.5 + i * 0.62, w: 2.5, h: 0.04,
      fill: { color: i === 3 ? C.tealLt : "1A3A5C" }, line: { color: i === 3 ? C.tealLt : "1A3A5C" }
    });
  }

  // Data source chip
  sl.addShape("rect", { x: 3.6, y: 1.05, w: 2.3, h: 0.3, fill: { color: "0D2B55" }, line: { color: C.teal, width: 1 } });
  sl.addText("HTTP Archive  •  State of the Web", {
    x: 3.6, y: 1.05, w: 2.3, h: 0.3,
    fontFace: FONT_BODY, fontSize: 8, color: C.tealLt, align: "center", valign: "middle", margin: 0
  });

  // Main title
  sl.addText("State of the Web", {
    x: 3.5, y: 1.5, w: 6.1, h: 0.7,
    fontFace: FONT_TITLE, fontSize: 38, bold: true, color: C.white, margin: 0
  });
  sl.addText("2020 – 2025", {
    x: 3.5, y: 2.22, w: 6.1, h: 0.62,
    fontFace: FONT_TITLE, fontSize: 38, bold: true, color: C.tealLt, margin: 0
  });

  // Subtitle
  sl.addText("Tracking Page Weight, Protocols & Security at Scale", {
    x: 3.5, y: 2.95, w: 6.1, h: 0.55,
    fontFace: FONT_BODY, fontSize: 16, color: C.offWht, margin: 0
  });

  // Divider
  sl.addShape("rect", { x: 3.5, y: 3.55, w: 5.8, h: 0.04, fill: { color: "1E3A5F" }, line: { color: "1E3A5F" } });

  // Meta line
  sl.addText([
    { text: "Data range: ", options: { color: C.muted, fontSize: 11 } },
    { text: "January 2020 – March 2026", options: { color: C.white, fontSize: 11, bold: true } },
    { text: "   |   ", options: { color: C.muted, fontSize: 11 } },
    { text: "Desktop & Mobile crawl data", options: { color: C.white, fontSize: 11 } }
  ], { x: 3.5, y: 3.7, w: 6.1, h: 0.35, margin: 0, fontFace: FONT_BODY });

  // Audience
  sl.addText("For web performance engineers and front-end architects", {
    x: 3.5, y: 4.15, w: 6.1, h: 0.28,
    fontFace: FONT_BODY, fontSize: 10, color: C.muted, italic: true, margin: 0
  });

  // Five topic pills
  const topics = ["Page Weight ↑", "HTTPS ~99%", "HTTP/3 Surge", "TCP ↓", "font-display"];
  topics.forEach((t, i) => {
    const px = 3.5 + i * 1.26;
    sl.addShape("rect", { x: px, y: 4.6, w: 1.18, h: 0.3, fill: { color: "0D2B55" }, line: { color: C.teal, width: 1 } });
    sl.addText(t, {
      x: px, y: 4.6, w: 1.18, h: 0.3,
      fontFace: FONT_BODY, fontSize: 8.5, color: C.tealLt, align: "center", valign: "middle", margin: 0
    });
  });
}

// ── SLIDE 2: Sample Size ──────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };
  headerBar(sl, "Crawl Sample Size Tripled: From ~5M to 16M Desktop URLs Since 2020");

  // Chart: dual-line time-series desktop vs mobile
  const years = ["Jan 2020","Jul 2020","Jan 2021","Jul 2021","Jan 2022","Jul 2022","Jan 2023","Jul 2023","Jan 2024","Jul 2024","Jan 2025"];
  const desktopVals = [5.0, 5.5, 6.0, 6.4, 7.0, 15.0, 16.2, 16.3, 16.4, 16.4, 16.5];
  const mobileVals  = [3.5, 4.0, 4.4, 4.8, 5.5, 10.0, 12.4, 12.5, 12.5, 12.5, 12.5];

  sl.addChart(pres.charts.LINE, [
    { name: "Desktop", labels: years, values: desktopVals },
    { name: "Mobile",  labels: years, values: mobileVals }
  ], {
    x: 0.45, y: 0.85, w: 6.5, h: 4.3,
    chartColors: [C.tealLt, C.amber],
    chartArea: { fill: { color: "0A1E35" } },
    catAxisLabelColor: C.muted,
    valAxisLabelColor: C.muted,
    valGridLine: { color: "1E3A5F", size: 0.5 },
    catGridLine: { style: "none" },
    lineSize: 3,
    lineSmooth: true,
    showLegend: true,
    legendPos: "b",
    legendColor: C.slate,
    valAxisTitle: "URLs (millions)",
    valAxisTitleColor: C.muted,
    showValAxisTitle: true,
    valAxisMaxVal: 20,
    valAxisMinVal: 0,
  });

  // Annotation cards — right panel
  statCard(sl, 7.15, 0.9, 2.5, 1.15, "16M", "Desktop URLs", "Current plateau (2023+)", C.tealLt);
  statCard(sl, 7.15, 2.2, 2.5, 1.15, "12.5M", "Mobile URLs", "Current plateau (2023+)", C.amber);
  statCard(sl, 7.15, 3.5, 2.5, 1.1, "3×", "Growth since Jan 2020", "Sharp jump: mid-2022", C.green);

  sourceLabel(sl);
}

// ── SLIDE 3: Page Weight ──────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };
  headerBar(sl, "Median Page Weight Climbs Steadily to ~2,000 KB on Desktop");

  const years = ["Jan 2020","Jul 2020","Jan 2021","Jul 2021","Jan 2022","Jul 2022","Jan 2023","Jul 2023","Jan 2024","Jul 2024","Jan 2025"];
  const desktop = [1600, 1650, 1700, 1740, 1800, 1850, 1900, 1940, 1960, 1985, 2000];
  const mobile  = [1520, 1570, 1620, 1660, 1720, 1770, 1820, 1860, 1880, 1900, 1920];
  const d75     = [3200, 3300, 3400, 3500, 3600, 3750, 3850, 3950, 4000, 4020, 4050];

  sl.addChart(pres.charts.LINE, [
    { name: "Desktop (median)", labels: years, values: desktop },
    { name: "Mobile (median)",  labels: years, values: mobile  },
    { name: "Desktop (p75)",    labels: years, values: d75     }
  ], {
    x: 0.45, y: 0.85, w: 6.5, h: 4.3,
    chartColors: [C.tealLt, C.amber, "5B6F8A"],
    chartArea: { fill: { color: "0A1E35" } },
    catAxisLabelColor: C.muted,
    valAxisLabelColor: C.muted,
    valGridLine: { color: "1E3A5F", size: 0.5 },
    catGridLine: { style: "none" },
    lineSize: 2.5,
    lineSmooth: true,
    showLegend: true,
    legendPos: "b",
    legendColor: C.slate,
    valAxisTitle: "Total KB",
    valAxisTitleColor: C.muted,
    showValAxisTitle: true,
    valAxisMaxVal: 4500,
    valAxisMinVal: 0,
  });

  // Stat cards
  statCard(sl, 7.15, 0.9,  2.5, 1.1, "~2,000 KB", "Desktop median", "Up ~25% from 2020", C.tealLt);
  statCard(sl, 7.15, 2.15, 2.5, 1.1, "~1,920 KB", "Mobile median",  "Tracking ~4% below desktop", C.amber);
  statCard(sl, 7.15, 3.4,  2.5, 1.1, ">4,000 KB", "Desktop p75",    "Long tail of heavy pages", "5B6F8A");

  sourceLabel(sl);
}

// ── SLIDE 4: Requests & Connections ──────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };
  headerBar(sl, "76 Requests per Desktop Page While TCP Connections Drop to 12");

  // Left: stat cards for requests
  sl.addShape("rect", { x: 0.45, y: 0.9, w: 4.1, h: 0.3, fill: { color: "061220" }, line: { color: "061220" } });
  sl.addText("REQUESTS PER PAGE (median)", {
    x: 0.45, y: 0.9, w: 4.1, h: 0.3,
    fontFace: FONT_BODY, fontSize: 9, bold: true, color: C.muted,
    charSpacing: 2, margin: 0, valign: "middle"
  });

  statCard(sl, 0.45, 1.25, 1.85, 1.35, "76",  "Desktop requests", "▲ 2.7% since 2020", C.tealLt);
