  // Audience
  sl.addText("For web performance engineers and front-end architects", {
    x: 3.5, y: 4.15, w: 6.1, h: 0.28,
    fontFace: FONT_BODY, fontSize: 10, color: C.muted, italic: true, margin: 0
  });

  // Five topic pills
  const topics = ["Page Weight ↑", "HTTPS ~99%", "HTTP/3 Surge", "TCP ↓", "font-display"];
  topics.forEach((t, i) => {
    const px = 3.5 + i * 1.26;
    sl.addShape("rect", { x: px, y: 4.6, w: 1.18, h: 0.3, fill: { color: "0D2B55" }, line: { color: C.teal, width: 1 } });
    sl.addText(t, {
      x: px, y: 4.6, w: 1.18, h: 0.3,
      fontFace: FONT_BODY, fontSize: 8.5, color: C.tealLt, align: "center", valign: "middle", margin: 0
    });
  });
}

// ── SLIDE 2: Sample Size ──────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };
  headerBar(sl, "Crawl Sample Size Tripled: From ~5M to 16M Desktop URLs Since 2020");

  // Chart: dual-line time-series desktop vs mobile
  const years = ["Jan 2020","Jul 2020","Jan 2021","Jul 2021","Jan 2022","Jul 2022","Jan 2023","Jul 2023","Jan 2024","Jul 2024","Jan 2025"];
  const desktopVals = [5.0, 5.5, 6.0, 6.4, 7.0, 15.0, 16.2, 16.3, 16.4, 16.4, 16.5];
  const mobileVals  = [3.5, 4.0, 4.4, 4.8, 5.5, 10.0, 12.4, 12.5, 12.5, 12.5, 12.5];

  sl.addChart(pres.charts.LINE, [
    { name: "Desktop", labels: years, values: desktopVals },
    { name: "Mobile",  labels: years, values: mobileVals }
  ], {
    x: 0.45, y: 0.85, w: 6.5, h: 4.3,
    chartColors: [C.tealLt, C.amber],
    chartArea: { fill: { color: "0A1E35" } },
    catAxisLabelColor: C.muted,
    valAxisLabelColor: C.muted,
