// ── Helpers ───────────────────────────────────────────────────
function headerBar(slide, title, { light = false } = {}) {
  // top accent line
  slide.addShape("rect", {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  // title text
  slide.addText(title, {
    x: 0.45, y: 0.14, w: 9.1, h: 0.55,
    fontFace: FONT_TITLE, fontSize: 22, bold: true,
    color: light ? C.dark : C.white,
    margin: 0
  });
  // subtle divider
  slide.addShape("rect", {
    x: 0.45, y: 0.72, w: 9.1, h: 0.02,
    fill: { color: light ? "CBD5E1" : "1E3A5F" }, line: { color: light ? "CBD5E1" : "1E3A5F" }
  });
}

function sourceLabel(slide, { light = false } = {}) {
  slide.addText("Source: HTTP Archive — State of the Web Report  |  Jan 2020 – Mar 2026", {
    x: 0.45, y: 5.4, w: 9.1, h: 0.2,
    fontFace: FONT_BODY, fontSize: 8, color: light ? "94A3B8" : "4A6A8A",
    margin: 0
  });
}

function statCard(slide, x, y, w, h, bigNum, label, sub, accent) {
  slide.addShape("rect", {
    x, y, w, h,
    fill: { color: C.card },
    line: { color: C.teal, width: 1 },
    shadow: { type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.25 }
  });
  // left accent bar
  slide.addShape("rect", {
    x, y, w: 0.06, h,
    fill: { color: accent || C.teal }, line: { color: accent || C.teal }
  });
  slide.addText(bigNum, {
    x: x + 0.15, y: y + 0.12, w: w - 0.2, h: h * 0.55,
    fontFace: FONT_TITLE, fontSize: 36, bold: true, color: C.tealLt,
    margin: 0, valign: "middle"
  });
  slide.addText(label, {
    x: x + 0.15, y: y + h * 0.6, w: w - 0.2, h: h * 0.22,
    fontFace: FONT_BODY, fontSize: 11, bold: true, color: C.white,
    margin: 0
  });
  if (sub) {
    slide.addText(sub, {
      x: x + 0.15, y: y + h * 0.82, w: w - 0.2, h: h * 0.18,
      fontFace: FONT_BODY, fontSize: 9, color: C.muted,
      margin: 0
    });
  }
}

