const pptxgen = require("/usr/local/lib/node_modules/pptxgenjs");

// ── Palette ───────────────────────────────────────────────────
const C = {
  dark:   "0A1628",
  navy:   "0D2B55",
  teal:   "0891B2",
  tealLt: "22D3EE",
  white:  "FFFFFF",
  offWht: "E0EAF4",
  muted:  "7CA3C8",
  card:   "112240",
  green:  "10B981",
  amber:  "F59E0B",
  slate:  "CBD5E1",
};

const F = "Calibri";

// ── Helpers ───────────────────────────────────────────────────
function headerBar(sl, title) {
  sl.addShape("rect", { x:0, y:0, w:10, h:0.07, fill:{color:C.teal}, line:{color:C.teal} });
  sl.addText(title, {
    x:0.45, y:0.13, w:9.1, h:0.58,
    fontFace:F, fontSize:20, bold:true, color:C.white, margin:0
  });
  sl.addShape("rect", { x:0.45, y:0.74, w:9.1, h:0.02, fill:{color:"1E3A5F"}, line:{color:"1E3A5F"} });
}

function sourceLabel(sl) {
  sl.addText("Source: HTTP Archive — State of the Web Report  |  Jan 2020 – Mar 2026", {
    x:0.45, y:5.38, w:9.1, h:0.2,
    fontFace:F, fontSize:7.5, color:"4A6A8A", margin:0
  });
}

// stat card: big number + two text rows below it. h should be ≥1.2 for comfort
function statCard(sl, x, y, w, h, bigNum, label, sub, accent) {
  sl.addShape("rect", {
    x, y, w, h,
    fill:{color:C.card}, line:{color:C.teal, width:1},
    shadow:{type:"outer",blur:6,offset:2,angle:135,color:"000000",opacity:0.2}
  });
  sl.addShape("rect", { x, y, w:0.065, h, fill:{color:accent||C.teal}, line:{color:accent||C.teal} });
  // big number — top 48% of card
  sl.addText(bigNum, {
    x:x+0.14, y:y+0.08, w:w-0.2, h:h*0.48,
    fontFace:F, fontSize:28, bold:true, color:C.tealLt,
    margin:0, valign:"bottom"
  });
  // label — 24%
  sl.addText(label, {
    x:x+0.14, y:y+h*0.56, w:w-0.2, h:h*0.24,
    fontFace:F, fontSize:10, bold:true, color:C.white,
    margin:0, valign:"top"
  });
  // sub — bottom 20%
  if (sub) {
    sl.addText(sub, {
      x:x+0.14, y:y+h*0.8, w:w-0.2, h:h*0.18,
      fontFace:F, fontSize:8.5, color:C.muted,
      margin:0, valign:"top"
    });
  }
}

// ── Presentation ──────────────────────────────────────────────
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title  = "State of the Web 2020–2025";

// ─────────────────────────────────────────────────────────────
// SLIDE 1 — Title
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.dark };

  // left accent panel
  sl.addShape("rect", { x:0, y:0, w:3.0, h:5.625, fill:{color:"061220"}, line:{color:"061220"} });
  sl.addShape("rect", { x:0, y:0, w:0.2,  h:5.625, fill:{color:C.teal},  line:{color:C.teal}  });

  // decorative horizontal bars in left panel — evenly spaced
  for (let i = 0; i < 9; i++) {
    const isTeal = i === 4;
    sl.addShape("rect", {
      x:0.38, y:0.4 + i * 0.54, w:2.3, h:0.04,
      fill:{color: isTeal ? C.tealLt : "1A3A5C"},
      line:{color: isTeal ? C.tealLt : "1A3A5C"}
    });
  }

  // source chip
  sl.addShape("rect", { x:3.5, y:0.95, w:2.6, h:0.32, fill:{color:"0D2B55"}, line:{color:C.teal,width:1} });
  sl.addText("HTTP Archive  •  State of the Web Report", {
    x:3.5, y:0.95, w:2.6, h:0.32,
    fontFace:F, fontSize:7.5, color:C.tealLt, align:"center", valign:"middle", margin:0
  });

  // title
  sl.addText("State of the Web", {
    x:3.4, y:1.42, w:6.2, h:0.72,
    fontFace:F, fontSize:40, bold:true, color:C.white, margin:0
  });
  sl.addText("2020 – 2025", {
    x:3.4, y:2.16, w:6.2, h:0.62,
    fontFace:F, fontSize:40, bold:true, color:C.tealLt, margin:0
  });

  // subtitle
  sl.addText("Tracking Page Weight, Protocols & Security at Scale", {
    x:3.4, y:2.9, w:6.2, h:0.48,
    fontFace:F, fontSize:15, color:C.offWht, margin:0
  });

  sl.addShape("rect", { x:3.4, y:3.46, w:6.0, h:0.03, fill:{color:"1E3A5F"}, line:{color:"1E3A5F"} });

  sl.addText([
    { text:"Data range: ", options:{color:C.muted, fontSize:10.5} },
    { text:"January 2020 – March 2026", options:{color:C.white, fontSize:10.5, bold:true} },
    { text:"   |   ", options:{color:C.muted, fontSize:10.5} },
    { text:"Desktop & Mobile crawl data", options:{color:C.white, fontSize:10.5} }
  ], { x:3.4, y:3.58, w:6.2, h:0.35, margin:0, fontFace:F });

  sl.addText("For web performance engineers and front-end architects", {
    x:3.4, y:4.0, w:6.2, h:0.28,
    fontFace:F, fontSize:9.5, color:C.muted, italic:true, margin:0
  });

  // topic pills — with more breathing room
  const topics = ["Page Weight ↑", "HTTPS ~99%", "HTTP/3 Surge", "TCP ↓", "font-display"];
  topics.forEach((t, i) => {
    const px = 3.4 + i * 1.24;
    sl.addShape("rect", { x:px, y:4.42, w:1.16, h:0.3, fill:{color:"0D2B55"}, line:{color:C.teal,width:1} });
    sl.addText(t, {
      x:px, y:4.42, w:1.16, h:0.3,
      fontFace:F, fontSize:8, color:C.tealLt, align:"center", valign:"middle", margin:0
    });
  });

  // bottom teal accent line with margin
  sl.addShape("rect", { x:3.4, y:4.85, w:6.0, h:0.05, fill:{color:C.teal}, line:{color:C.teal} });

  sl.addText("httparchive.org", {
    x:3.4, y:4.98, w:6.2, h:0.25,
    fontFace:F, fontSize:9, color:"4A6A8A", margin:0
  });
}

// ─────────────────────────────────────────────────────────────
// SLIDE 2 — Sample Size
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };
  headerBar(sl, "Crawl Sample Size Tripled: From ~5M to 16M Desktop URLs Since 2020");

  const years = ["Jan'20","Jul'20","Jan'21","Jul'21","Jan'22","Jul'22","Jan'23","Jul'23","Jan'24","Jul'24","Jan'25"];
  const desk  = [5.0, 5.5, 6.0, 6.4, 7.0, 15.0, 16.2, 16.3, 16.4, 16.4, 16.5];
  const mob   = [3.5, 4.0, 4.4, 4.8, 5.5, 10.0, 12.4, 12.5, 12.5, 12.5, 12.5];

  sl.addChart(pres.charts.LINE, [
    { name:"Desktop", labels:years, values:desk },
    { name:"Mobile",  labels:years, values:mob  }
  ], {
    x:0.45, y:0.85, w:6.4, h:4.35,
    chartColors:[C.tealLt, C.amber],
    chartArea:{ fill:{color:"0A1E35"} },
    catAxisLabelColor:C.muted, valAxisLabelColor:C.muted,
    valGridLine:{color:"1E3A5F",size:0.5}, catGridLine:{style:"none"},
    lineSize:3, lineSmooth:true,
    showLegend:true, legendPos:"b", legendColor:C.slate,
    valAxisMaxVal:20, valAxisMinVal:0,
    showValAxisTitle:true, valAxisTitle:"URLs (millions)", valAxisTitleColor:C.muted,
  });

  statCard(sl, 7.1, 0.9,  2.55, 1.2, "16M",   "Desktop URLs",        "Plateau from 2023+",  C.tealLt);
  statCard(sl, 7.1, 2.22, 2.55, 1.2, "12.5M", "Mobile URLs",         "Plateau from 2023+",  C.amber);
  statCard(sl, 7.1, 3.54, 2.55, 1.2, "3×",    "Growth since 2020",   "Sharp jump: mid-2022", C.green);

  sourceLabel(sl);
}

// ─────────────────────────────────────────────────────────────
// SLIDE 3 — Page Weight
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };
  headerBar(sl, "Median Page Weight Climbs Steadily to ~2,000 KB on Desktop");

  const years = ["Jan'20","Jul'20","Jan'21","Jul'21","Jan'22","Jul'22","Jan'23","Jul'23","Jan'24","Jul'24","Jan'25"];
  const desk  = [1600,1650,1700,1740,1800,1850,1900,1940,1960,1985,2000];
  const mob   = [1520,1570,1620,1660,1720,1770,1820,1860,1880,1900,1920];
  const d75   = [3200,3300,3400,3500,3600,3750,3850,3950,4000,4020,4050];

  sl.addChart(pres.charts.LINE, [
    { name:"Desktop (median)", labels:years, values:desk },
    { name:"Mobile (median)",  labels:years, values:mob  },
    { name:"Desktop (p75)",    labels:years, values:d75  }
  ], {
    x:0.45, y:0.85, w:6.4, h:4.35,
    chartColors:[C.tealLt, C.amber, "5B6F8A"],
    chartArea:{ fill:{color:"0A1E35"} },
    catAxisLabelColor:C.muted, valAxisLabelColor:C.muted,
    valGridLine:{color:"1E3A5F",size:0.5}, catGridLine:{style:"none"},
    lineSize:2.5, lineSmooth:true,
    showLegend:true, legendPos:"b", legendColor:C.slate,
    valAxisMaxVal:4500, valAxisMinVal:0,
    showValAxisTitle:true, valAxisTitle:"Total KB", valAxisTitleColor:C.muted,
  });

  statCard(sl, 7.1, 0.9,  2.55, 1.2, "~2,000 KB", "Desktop median",      "Up ~25% from 2020",           C.tealLt);
  statCard(sl, 7.1, 2.22, 2.55, 1.2, "~1,920 KB", "Mobile median",       "~4% below desktop",           C.amber);
  statCard(sl, 7.1, 3.54, 2.55, 1.2, ">4,000 KB", "Desktop p75",         "Long tail of heavy pages",    "5B6F8A");

  sourceLabel(sl);
}

// ─────────────────────────────────────────────────────────────
// SLIDE 4 — Requests & Connections
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };
  headerBar(sl, "76 Requests per Desktop Page While TCP Connections Drop to 12");

  // ── LEFT column: request stat cards + note ────────────────
  // section label
  sl.addText("REQUESTS PER PAGE  (median)", {
    x:0.45, y:0.84, w:4.0, h:0.26,
    fontFace:F, fontSize:8.5, bold:true, color:C.muted, charSpacing:2, margin:0
  });
  statCard(sl, 0.45, 1.14, 1.82, 1.35, "76", "Desktop requests", "▲ 2.7% since 2020", C.tealLt);
  statCard(sl, 2.38, 1.14, 1.82, 1.35, "71", "Mobile requests",  "▲ 2.9% since 2020", C.amber);

  // observation note
  sl.addShape("rect", { x:0.45, y:2.6, w:3.75, h:0.62, fill:{color:C.card}, line:{color:"1E3A5F"} });
  sl.addText([
    { text:"Request growth is modest (~3%) despite heavier pages — ", options:{color:C.offWht} },
    { text:"browsers load fewer but larger assets", options:{color:C.tealLt, bold:true} }
  ], { x:0.58, y:2.65, w:3.5, h:0.52, fontFace:F, fontSize:9.5, margin:0 });

  // TCP section label
  sl.addText("TCP CONNECTIONS PER PAGE  (median) — DECLINING", {
    x:0.45, y:3.34, w:4.0, h:0.26,
    fontFace:F, fontSize:8.5, bold:true, color:C.muted, charSpacing:2, margin:0
  });
  statCard(sl, 0.45, 3.64, 1.82, 1.3, "15→12", "Desktop TCP",  "▼ 14.3% decline", C.tealLt);
  statCard(sl, 2.38, 3.64, 1.82, 1.3, "15→11", "Mobile TCP",   "▼ 26.7% decline", C.amber);

  // ── RIGHT column: TCP line chart ──────────────────────────
  sl.addText("TCP connections per page, 2020–2025", {
    x:4.65, y:0.84, w:5.0, h:0.28,
    fontFace:F, fontSize:10, bold:true, color:C.offWht, margin:0
  });

  const years = ["Jan'20","Jul'20","Jan'21","Jul'21","Jan'22","Jul'22","Jan'23","Jul'23","Jan'24","Jul'24","Jan'25"];
  const tcpD  = [15,14.5,14,13.5,13.2,13.0,12.6,12.4,12.2,12.1,12.0];
  const tcpM  = [15,14.2,13.5,13.0,12.5,12.0,11.6,11.3,11.1,11.0,11.0];

  sl.addChart(pres.charts.LINE, [
    { name:"Desktop TCP", labels:years, values:tcpD },
    { name:"Mobile TCP",  labels:years, values:tcpM }
  ], {
    x:4.55, y:1.16, w:5.1, h:3.5,
    chartColors:[C.tealLt, C.amber],
    chartArea:{ fill:{color:"0A1E35"} },
    catAxisLabelColor:C.muted, valAxisLabelColor:C.muted,
    valGridLine:{color:"1E3A5F",size:0.5}, catGridLine:{style:"none"},
    lineSize:3, lineSmooth:true,
    showLegend:true, legendPos:"b", legendColor:C.slate,
    valAxisMaxVal:17, valAxisMinVal:9,
  });

  sl.addShape("rect", { x:4.55, y:4.74, w:5.1, h:0.38, fill:{color:C.card}, line:{color:C.teal,width:1} });
  sl.addText("Multiplexing via HTTP/2 & HTTP/3 reduces TCP overhead per page", {
    x:4.65, y:4.79, w:4.9, h:0.28,
    fontFace:F, fontSize:9, color:C.tealLt, italic:true, margin:0
  });

  sourceLabel(sl);
}

// ─────────────────────────────────────────────────────────────
// SLIDE 5 — HTTPS
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.dark };

  // top accent — green for security theme
  sl.addShape("rect", { x:0, y:0, w:10, h:0.07, fill:{color:C.green}, line:{color:C.green} });
  sl.addText("HTTPS Requests Reach 99%: Encryption Is Now the Default", {
    x:0.45, y:0.13, w:9.1, h:0.58,
    fontFace:F, fontSize:20, bold:true, color:C.white, margin:0
  });
  sl.addShape("rect", { x:0.45, y:0.74, w:9.1, h:0.02, fill:{color:"1E3A5F"}, line:{color:"1E3A5F"} });

  // LEFT callout panel
  sl.addShape("rect", { x:0.45, y:0.88, w:3.9, h:4.3, fill:{color:"061A10"}, line:{color:C.green,width:2} });
  sl.addShape("rect", { x:0.45, y:0.88, w:3.9, h:0.09, fill:{color:C.green}, line:{color:C.green} });

  sl.addText("99%+", {
    x:0.55, y:1.1, w:3.7, h:1.4,
    fontFace:F, fontSize:78, bold:true, color:C.green,
    align:"center", valign:"middle", margin:0
  });
  sl.addText("of all web requests use HTTPS", {
    x:0.55, y:2.58, w:3.7, h:0.38,
    fontFace:F, fontSize:13, color:C.white, align:"center", margin:0
  });

  // sub-stat boxes — with more spacing
  sl.addShape("rect", { x:0.6, y:3.08, w:1.65, h:0.82, fill:{color:"0A2A14"}, line:{color:"14532D",width:1} });
  sl.addText([
    { text:"99.2%", options:{bold:true, fontSize:18, color:C.green, breakLine:true} },
    { text:"Desktop", options:{fontSize:9, color:C.slate} }
  ], { x:0.6, y:3.08, w:1.65, h:0.82, fontFace:F, align:"center", valign:"middle", margin:0 });

  sl.addShape("rect", { x:2.4, y:3.08, w:1.65, h:0.82, fill:{color:"0A2A14"}, line:{color:"14532D",width:1} });
  sl.addText([
    { text:"99.1%", options:{bold:true, fontSize:18, color:C.green, breakLine:true} },
    { text:"Mobile", options:{fontSize:9, color:C.slate} }
  ], { x:2.4, y:3.08, w:1.65, h:0.82, fontFace:F, align:"center", valign:"middle", margin:0 });

  sl.addShape("rect", { x:0.6, y:4.02, w:3.45, h:0.72, fill:{color:"0A2A14"}, line:{color:"14532D"} });
  sl.addText([
    { text:"↑ ~19–20 percentage points since 2020\n", options:{bold:true, color:C.green, fontSize:10} },
    { text:"Plaintext HTTP is effectively extinct on the modern web", options:{color:C.slate, fontSize:9} }
  ], { x:0.7, y:4.07, w:3.25, h:0.6, fontFace:F, align:"center", margin:0 });

  // RIGHT chart
  sl.addText("HTTPS adoption over time (%)", {
    x:4.6, y:0.88, w:5.0, h:0.28,
    fontFace:F, fontSize:10, bold:true, color:C.offWht, margin:0
  });

  const years = ["Jan'20","Jul'20","Jan'21","Jul'21","Jan'22","Jul'22","Jan'23","Jul'23","Jan'24","Jul'24","Jan'25"];
  const httpsD = [80,83,86,88,90,92,94,96,97.5,98.5,99.2];
  const httpsM = [79,82,85,87,89,91,93,95,97.0,98.2,99.1];

  sl.addChart(pres.charts.LINE, [
    { name:"Desktop HTTPS%", labels:years, values:httpsD },
    { name:"Mobile HTTPS%",  labels:years, values:httpsM }
  ], {
    x:4.5, y:1.2, w:5.15, h:4.0,
    chartColors:[C.green, C.amber],
    chartArea:{ fill:{color:"061A10"} },
    catAxisLabelColor:C.muted, valAxisLabelColor:C.muted,
    valGridLine:{color:"0D2B1A",size:0.5}, catGridLine:{style:"none"},
    lineSize:3, lineSmooth:true,
    showLegend:true, legendPos:"b", legendColor:C.slate,
    valAxisMaxVal:100, valAxisMinVal:70,
  });

  sourceLabel(sl);
}

// ─────────────────────────────────────────────────────────────
// SLIDE 6 — HTTP/2 & HTTP/3
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };
  headerBar(sl, "HTTP/2 Holds at ~58% While HTTP/3 Support Surges to 40%");

  // LEFT: grouped bar chart
  sl.addText("Latest snapshot — protocol share by platform", {
    x:0.45, y:0.84, w:5.7, h:0.28,
    fontFace:F, fontSize:10, bold:true, color:C.offWht, margin:0
  });
  sl.addChart(pres.charts.BAR, [
    { name:"Desktop", labels:["HTTP/2","HTTP/3 Support"], values:[58.6, 38.7] },
    { name:"Mobile",  labels:["HTTP/2","HTTP/3 Support"], values:[57.6, 40.0] }
  ], {
    x:0.45, y:1.15, w:5.6, h:3.5,
    barDir:"col", barGrouping:"clustered",
    chartColors:[C.tealLt, C.amber],
    chartArea:{ fill:{color:"0A1E35"} },
    catAxisLabelColor:C.muted, valAxisLabelColor:C.muted,
    valGridLine:{color:"1E3A5F",size:0.5}, catGridLine:{style:"none"},
    showValue:true, dataLabelPosition:"outEnd",
    dataLabelColor:C.white, dataLabelFontSize:10,
    showLegend:true, legendPos:"b", legendColor:C.slate,
    valAxisMaxVal:80, valAxisMinVal:0,
  });

  // RIGHT: HTTP/3 inset trend + stat cards
  sl.addText("HTTP/3 desktop support — rapid rise", {
    x:6.3, y:0.84, w:3.35, h:0.28,
    fontFace:F, fontSize:9, bold:true, color:C.muted, margin:0
  });
  const yrs3 = ["2020","2021","2022","2023","2024","2025"];
  const h3D  = [0.1, 2, 10, 22, 32, 38.7];
  sl.addChart(pres.charts.LINE, [
    { name:"HTTP/3 Desktop %", labels:yrs3, values:h3D }
  ], {
    x:6.2, y:1.15, w:3.45, h:2.2,
    chartColors:[C.tealLt],
    chartArea:{ fill:{color:"0A1E35"} },
    catAxisLabelColor:C.muted, valAxisLabelColor:C.muted,
    valGridLine:{color:"1E3A5F",size:0.5}, catGridLine:{style:"none"},
    lineSize:3, lineSmooth:true, showLegend:false,
    valAxisMaxVal:45, valAxisMinVal:0,
  });

  // stat cards — right side, below inset chart
  statCard(sl, 6.2,  3.5, 1.62, 1.1, "58.6%", "HTTP/2",  "Desktop requests", C.tealLt);
  statCard(sl, 7.98, 3.5, 1.62, 1.1, "38.7%", "HTTP/3",  "Desktop support",  C.amber);

  // caveat note
  sl.addShape("rect", { x:0.45, y:4.74, w:9.2, h:0.48, fill:{color:C.card}, line:{color:"1E3A5F"} });
  sl.addText([
    { text:"Measurement note: ", options:{bold:true, color:C.tealLt} },
    { text:"HTTP Archive measures HTTP/3 ", options:{color:C.offWht} },
    { text:"support", options:{italic:true, color:C.offWht} },
    { text:", not usage. Fresh Chrome instances default to HTTP/2 on first connection, then discover HTTP/3 via Alt-Svc headers.", options:{color:C.offWht} }
  ], { x:0.6, y:4.79, w:9.0, h:0.38, fontFace:F, fontSize:9, margin:0 });

  sourceLabel(sl);
}

// ─────────────────────────────────────────────────────────────
// SLIDE 7 — font-display
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.navy };
  headerBar(sl, "Font-Display Usage Reaches 42% on Mobile, Up 61% Since 2020");

  const years = ["Jan'20","Jul'20","Jan'21","Jul'21","Jan'22","Jul'22","Jan'23","Jul'23","Jan'24","Jul'24","Jan'25"];
  const fdD = [34.9,35.5,36.2,36.8,37.5,38.0,38.7,39.2,39.6,40.0,40.1];
  const fdM = [26.4,28.0,29.5,31.0,33.0,35.5,37.5,39.5,41.0,42.0,42.5];

  sl.addChart(pres.charts.LINE, [
    { name:"Desktop", labels:years, values:fdD },
    { name:"Mobile",  labels:years, values:fdM }
  ], {
    x:0.45, y:0.85, w:6.4, h:4.35,
    chartColors:[C.tealLt, C.amber],
    chartArea:{ fill:{color:"0A1E35"} },
    catAxisLabelColor:C.muted, valAxisLabelColor:C.muted,
    valGridLine:{color:"1E3A5F",size:0.5}, catGridLine:{style:"none"},
    lineSize:3, lineSmooth:true,
    showLegend:true, legendPos:"b", legendColor:C.slate,
    showValAxisTitle:true, valAxisTitle:"% of pages", valAxisTitleColor:C.muted,
    valAxisMaxVal:55, valAxisMinVal:0,
  });

  statCard(sl, 7.1, 0.88, 2.55, 1.2, "40.1%", "Desktop",  "▲ 14.9% since 2020", C.tealLt);
  statCard(sl, 7.1, 2.18, 2.55, 1.2, "42.5%", "Mobile",   "▲ 61.0% since 2020", C.amber);

  // FOIT explainer card
  sl.addShape("rect", { x:7.1, y:3.5, w:2.55, h:1.7, fill:{color:C.card}, line:{color:"1E3A5F"} });
  sl.addShape("rect", { x:7.1, y:3.5, w:0.065, h:1.7, fill:{color:C.amber}, line:{color:C.amber} });
  sl.addText("What is font-display?", {
    x:7.22, y:3.56, w:2.35, h:0.3,
    fontFace:F, fontSize:10, bold:true, color:C.amber, margin:0
  });
  sl.addText([
    { text:"A CSS property controlling how web fonts load. Without it, browsers show ", options:{} },
    { text:"invisible text (FOIT) ", options:{bold:true} },
    { text:"until the font arrives.\n\n", options:{} },
    { text:">57% of pages still at risk.", options:{bold:true, color:C.amber} }
  ], {
    x:7.22, y:3.9, w:2.35, h:1.22,
    fontFace:F, fontSize:9, color:C.offWht, margin:0
  });

  sourceLabel(sl);
}

// ─────────────────────────────────────────────────────────────
// SLIDE 8 — Key Takeaways
// ─────────────────────────────────────────────────────────────
{
  const sl = pres.addSlide();
  sl.background = { color: C.dark };

  sl.addShape("rect", { x:0, y:0, w:10, h:0.07, fill:{color:C.teal}, line:{color:C.teal} });
  sl.addText("Key Takeaways", {
    x:0.45, y:0.13, w:9.1, h:0.52,
    fontFace:F, fontSize:22, bold:true, color:C.white, margin:0
  });
  sl.addText("Bigger Pages, Smarter Protocols, Stronger Security", {
    x:0.45, y:0.62, w:9.1, h:0.28,
    fontFace:F, fontSize:13, color:C.muted, margin:0
  });

  const findings = [
    { num:"01", head:"Page weight keeps climbing",
      body:"Median desktop pages now transfer ~2,000 KB — up ~25% from 2020 — driven by richer media and JavaScript.",
      accent:C.tealLt },
    { num:"02", head:"HTTPS is now the baseline",
      body:"99%+ of all requests use HTTPS. Unencrypted HTTP is effectively extinct on the modern web.",
      accent:C.green },
    { num:"03", head:"HTTP/3 is fastest-growing",
      body:"From near-zero to ~40% support in under 4 years. HTTP/3 is rapidly becoming mainstream.",
      accent:C.amber },
    { num:"04", head:"Fewer TCP connections",
      body:"HTTP/2 and HTTP/3 multiplexing cut median TCP connections per page by 15–27%, improving efficiency.",
      accent:C.tealLt },
    { num:"05", head:"Font-display still underused",
      body:"Only ~40–42% of pages use font-display. More than half still risk invisible text during font loading.",
      accent:C.amber },
  ];

  // 3-column layout: col1=[0,1,2], col2=[3,4]  — use equal card widths
  const cardW = 4.4;
  const cardH = 1.08;
  const gap   = 0.15;
  const col1x = 0.45;
  const col2x = 5.2;

  // Left col: findings 0,1,2
  [0,1,2].forEach((fi, ri) => {
    const f = findings[fi];
    const y = 1.0 + ri * (cardH + gap);
    sl.addShape("rect", { x:col1x, y, w:cardW, h:cardH, fill:{color:C.card}, line:{color:"1A3050"} });
    sl.addShape("rect", { x:col1x, y, w:0.065, h:cardH, fill:{color:f.accent}, line:{color:f.accent} });
    sl.addText(f.num, {
      x:col1x+0.16, y:y+0.06, w:0.45, h:0.34,
      fontFace:F, fontSize:17, bold:true, color:f.accent, margin:0
    });
    sl.addText(f.head, {
      x:col1x+0.62, y:y+0.08, w:cardW-0.72, h:0.32,
      fontFace:F, fontSize:11.5, bold:true, color:C.white, margin:0
    });
    sl.addText(f.body, {
      x:col1x+0.16, y:y+0.44, w:cardW-0.24, h:0.58,
      fontFace:F, fontSize:9.5, color:C.slate, margin:0
    });
  });

  // Right col: findings 3,4
  [3,4].forEach((fi, ri) => {
    const f = findings[fi];
    const y = 1.0 + ri * (cardH + gap);
    sl.addShape("rect", { x:col2x, y, w:cardW, h:cardH, fill:{color:C.card}, line:{color:"1A3050"} });
    sl.addShape("rect", { x:col2x, y, w:0.065, h:cardH, fill:{color:f.accent}, line:{color:f.accent} });
    sl.addText(f.num, {
      x:col2x+0.16, y:y+0.06, w:0.45, h:0.34,
      fontFace:F, fontSize:17, bold:true, color:f.accent, margin:0
    });
    sl.addText(f.head, {
      x:col2x+0.62, y:y+0.08, w:cardW-0.72, h:0.32,
      fontFace:F, fontSize:11.5, bold:true, color:C.white, margin:0
    });
    sl.addText(f.body, {
      x:col2x+0.16, y:y+0.44, w:cardW-0.24, h:0.58,
      fontFace:F, fontSize:9.5, color:C.slate, margin:0
    });
  });

  // CTA banner
  sl.addShape("rect", { x:0.45, y:4.73, w:9.1, h:0.48, fill:{color:"0D3A5C"}, line:{color:C.teal,width:1} });
  sl.addText([
    { text:"Benchmark your site: ", options:{bold:true, color:C.tealLt} },
    { text:"Compare page weight, HTTPS coverage, protocol mix, and font-display usage against these baselines at ", options:{color:C.offWht} },
    { text:"httparchive.org/reports/state-of-the-web", options:{color:C.tealLt, bold:true} }
  ], { x:0.6, y:4.78, w:8.8, h:0.38, fontFace:F, fontSize:9.5, margin:0 });

  sl.addText("Source: HTTP Archive — State of the Web Report  |  Jan 2020 – Mar 2026", {
    x:0.45, y:5.27, w:9.1, h:0.2,
    fontFace:F, fontSize:7.5, color:"4A6A8A", margin:0
  });
}

// ── Write ─────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Done: /app/output/final_deck.pptx"))
  .catch(e => { console.error(e); process.exit(1); });

