  // 2-col × 3-row grid: [01,02] top, [03,04] mid, [05, empty→wide CTA] bottom
  // Use equal card heights and widths so the grid fills evenly
  const cardW = 4.4;
  const cardH = 1.05;
  const gap   = 0.14;
  const col1x = 0.45;
  const col2x = 5.2;

  // grid: 3 rows × 2 cols = 6 slots; findings fill slots 0–4, slot 5 unused
  const grid = [
    [0, 1],  // row 0
    [2, 3],  // row 1
    [4, null], // row 2 — right slot will be replaced by a wide CTA
  ];

  grid.forEach(([left, right], row) => {
    const y = 1.0 + row * (cardH + gap);

    [left, right].forEach((fi, col) => {
      if (fi === null) return;
      const f = findings[fi];
      const x = col === 0 ? col1x : col2x;
      sl.addShape("rect", { x, y, w:cardW, h:cardH, fill:{color:C.card}, line:{color:"1A3050"} });
      sl.addShape("rect", { x, y, w:0.065, h:cardH, fill:{color:f.accent}, line:{color:f.accent} });
      sl.addText(f.num, {
        x:x+0.16, y:y+0.06, w:0.45, h:0.32,
        fontFace:F, fontSize:16, bold:true, color:f.accent, margin:0
      });
      sl.addText(f.head, {
        x:x+0.62, y:y+0.06, w:cardW-0.72, h:0.32,
        fontFace:F, fontSize:11.5, bold:true, color:C.white, margin:0
      });
      sl.addText(f.body, {
        x:x+0.16, y:y+0.42, w:cardW-0.24, h:0.57,
        fontFace:F, fontSize:9.5, color:C.slate, margin:0
      });
    });
  });

  // CTA banner — spans full width below the 3 rows
  const ctaY = 1.0 + 3 * (cardH + gap);
  sl.addShape("rect", { x:0.45, y:ctaY, w:9.1, h:0.52, fill:{color:"0D3A5C"}, line:{color:C.teal,width:1} });
